  1	<?php
  2	
  3	namespace Modules\AI\Domain\Decision;
  4	
  5	use Carbon\CarbonImmutable;
  6	use Modules\AI\Domain\Doctrine\ArchetypeDoctrine;
  7	use Modules\AI\Domain\Persona\SavingsGoal;
  8	use Modules\AI\Enums\AiStockpileStrategy;
  9	use Modules\AI\Models\AiProfile;
 10	use OGame\Factories\PlayerServiceFactory;
 11	use OGame\GameObjects\Models\Enums\GameObjectType;
 12	use OGame\Models\Resources;
 13	use OGame\Models\User;
 14	use OGame\Services\BuildingQueueService;
 15	use OGame\Services\ObjectService;
 16	use OGame\Services\PlanetService;
 17	use OGame\Services\PlayerService;
 18	use OGame\Services\ResearchQueueService;
 19	
 20	/**
 21	 * Answers one question about the account's own economy: is there a building or a technology it can
 22	 * legally queue now, and on which planet?
 23	 *
 24	 * Two things want a building. The chain wants the facility a later capability cannot exist without
 25	 * -- an account with no research lab can never research, and one with no shipyard can never own a
 26	 * ship -- and the economy wants the upgrade that repays itself fastest, or the storage that is about
 27	 * to overflow. The plan runs in two passes across the account's planets: first a warehouse that is
 28	 * about to overflow anywhere (it stops that planet producing, so it outranks every routine step on
 29	 * every other planet), then the routine economy planet by planet -- the energy a planet needs before
 30	 * it throttles, the chain's facilities, then the fastest-paying mine. The cross-planet storage pass
 31	 * is what keeps a full warehouse on one colony from waiting behind a routine mine on the homeworld.
 32	 *
 33	 * Both are only suggestions. Every gate is the host's own -- planet type, free queue space,
 34	 * requirements met against what is built *and* queued, and a price the planet can pay, which is the
 35	 * same set the building page shows a human -- so the module never restates an OGame rule. A target
 36	 * the host rejects is not an error but a fall-through: the planner tries the next one, which is what
 37	 * keeps a single impossible favourite from costing the account its whole build capability.
 38	 *
 39	 * Affordability is a real gate rather than a nicety: `BuildingQueueService::start()` cancels a queue
 40	 * item it cannot pay for, so publishing `build` while short of resources spends a queue slot and
 41	 * reports nothing at all.
 42	 */
 43	class QueueableBuildingPlanner
 44	{
 45	    /** The lab is one queue for the account, so its step has one slot beside the per-planet building steps. */
 46	    private const LAB_STEP = 'lab';
 47	
 48	    /** The pass that stands the facilities a bare planet's wall waits on: it is a fix, not a choice. */
 49	    private const WALL_STEP = 'wall';
 50	
 51	    public function __construct(
 52	        private PlayerServiceFactory $playerServiceFactory,
 53	        private FacilityChain $facilityChain,
 54	        private EnergyCapacity $energyCapacity,
 55	        private EconomyUpgrades $economyUpgrades,
 56	        private ReserveFloor $reserveFloor,
 57	        private BuildingQueueService $buildingQueueService,
 58	        private ResearchQueueService $researchQueueService,
 59	    ) {
 60	    }
 61	
 62	    public function plan(int $playerId, ?PlayerService $player = null): QueueableBuilding|QueueableResearch|null
 63	    {
 64	        return $this->steps($playerId, $player, 1)[0] ?? null;
 65	    }
 66	
 67	    /**
 68	     * Every queue a player would fill in one login: at most one building per planet, because each planet
 69	     * pays from its own stock and has its own build queue, and at most one technology, because the
 70	     * lab is one queue for the account. The order is plan()'s, so the first step is the one plan()
 71	     * returns.
 72	     *
 73	     * @return list<QueueableBuilding|QueueableResearch>
 74	     */
 75	    public function steps(int $playerId, ?PlayerService $player = null, int $limit = PHP_INT_MAX): array
 76	    {
 77	        // An account the module does not manage has no policy to apply, so it gets no capability.
 78	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 79	        if ($profile === null) {
 80	            return [];
 81	        }
 82	
 83	        // The module owns profile rows; the host owns accounts. A profile can outlive its account or
 84	        // be written by a fixture, and loading an account the host does not have throws -- so the
 85	        // precondition is asked here rather than discovered in the host service.
 86	        if (!User::query()->whereKey($playerId)->exists()) {
 87	            return [];
 88	        }
 89	
 90	        // Refresh every planet's live balance once: the candidate pass reads stored amounts and
 91	        // energy, and a balance read stale is exactly the balance the queue later cancels on. The
 92	        // refresh stays in memory -- the observation path must not write.
 93	        $planets = ($player ?? $this->playerServiceFactory->make($playerId, true))->planets->all();
 94	        foreach ($planets as $planet) {
 95	            $planet->updateResources(false);
 96	            $planet->updateResourceProductionStats(false);
 97	            $planet->updateResourceStorageStats(false);
 98	        }
 99	
100	        $passes = $this->passes($profile);
101	
102	        // What every planet is holding back, once per session: reading it walks the same candidate
103	        // lists the passes do, so asking again inside each pass would repeat a planet's whole economy,
104	        // and a planet's hold is its own.
105	        // It is also what keeps this list honest: the cohort reads "buildable" from exactly these
106	        // steps, so a planet whose pile the goal reserves must not be offered here -- otherwise the
107	        // read-out says buildable while the account rightly saves, and the invariant flags a saver
108	        // for behaving as designed.
109	        $goals = [];
110	        foreach ($planets as $planet) {
111	            $goals[$planet->getPlanetId()] = $this->savingsGoal($planet, $profile);
112	        }
113	
114	        $steps = [];
115	        foreach ($passes as $pass => $candidates) {
116	            foreach ($planets as $planet) {
117	                if (count($steps) >= $limit) {
118	                    return array_values($steps);
119	                }
120	
121	                $steps = $this->withStep($steps, $planet, $profile, $candidates, $goals[$planet->getPlanetId()], $pass === self::WALL_STEP);
122	            }
123	        }
124	
125	        return array_values($steps);
126	    }
127	
128	    /**
129	     * The candidate lists in the order the planner tries them. A warehouse about to overflow stops
130	     * that planet producing, so its pass runs across every planet before any routine step; a full
131	     * warehouse (E7) is a spend signal and comes next; then the routine economy: energy before it
132	     * throttles, the chain's facilities, the fastest-paying mine. Public so a read-out explains a
133	     * planet with the same lists the decision used.
134	     *
135	     * @return array<string, callable(PlanetService): list<BuildCandidate>>
136	     */
137	    public function passes(AiProfile $profile): array
138	    {
139	        return [
140	            // A planet holding no defence while a sibling already stands a wall is past the
141	            // account's opening with a sibling walled everywhere else: the facilities the wall
142	            // itself waits on come before the economy, so the planet is not left naked behind a
143	            // stock it is busy spending (QUAL-003). The step is the same shape as a wall order: a
144	            // saving the economy is holding back does not veto it, because a planet with no wall is
145	            // the state the account is fixing, not a step it chooses between (QUAL-003).
146	            'wall' => fn (PlanetService $planet): array => $this->facilityChain->wallPending($planet),
147	            // The archetype's written opening and research path (architecture step 4): the build list a guide
148	            // gives, in order, before the payback rules below take over. An object the host lacks is skipped.
149	            'doctrine' => fn (PlanetService $planet): array => [
150	                ...app(ArchetypeDoctrine::class)->openingStep($profile->archetype, $planet),
151	                ...($planet->getPlayer() !== null ? app(ArchetypeDoctrine::class)->researchStep($profile->archetype, $planet->getPlayer()) : []),
152	            ],
153	            'storage' => fn (PlanetService $planet): array => $this->economyUpgrades->storage($planet, $profile),
154	            'surplus' => fn (PlanetService $planet): array => $this->economyUpgrades->spendSurplus($planet, $profile),
155	            'routine' => function (PlanetService $planet) use ($profile): array {
156	                // The mine that repays today is an immediate need, so it also gates the station project
157	                // below: a planet whose mines still repay is not settled, and it keeps mining.
158	                $paying = $this->economyUpgrades->production($planet, $profile);
159	
160	                return [
161	                    ...$this->energyCapacity->pending($planet),
162	                    // A station the host's catalogue offers and this planet does not hold is a goal with a
163	                    // list of its own (FacilityChain::stationPending). The chain's one ambition is its next
164	                    // war hull, and the station the account could already hold is skipped as "producible",
165	                    // so the facilities only a station waits on were never asked for and the deepest
166	                    // stations stayed unowned (COVER-OBJECTS-001). It comes after the capacity the host
167	                    // throttles the planet without, and before the war hull, which is a goal on every
168	                    // login of every account that owns a ship and would otherwise never give it a turn.
169	                    ...($this->minesOutgrownStations($planet, $paying) ? $this->facilityChain->stationPending($planet) : []),
170	                    ...$this->facilityChain->pending($planet),
171	                    ...$this->economyUpgrades->storageForPrice($planet, $profile),
172	                    ...$paying,
173	                ];
174	            },
175	            // A planet sitting on six times the price of a facility it does not own buys it -- but only
176	            // once nothing urgent is left, which is what that pass says it is for: the capacity the host
177	            // throttles the planet without, the prerequisites the rest of the game is gated behind and the
178	            // mine that repays first all outrank a facility bought for its own sake (COVER-*). Placed
179	            // ahead of them it bought a robotics factory on a planet that could not yet cover its mines
180	            // (measured: AiCapabilityPublicationTest, EnergyCapacityTest).
181	            'ambition' => fn (PlanetService $planet): array => $this->economyUpgrades->ambitions($planet),
182	        ];
183	    }
184	
185	    /**
186	     * The build queue and the lab run side by side, so a planet's building and the account's one
187	     * technology are separate steps: a planet whose best candidate is a technology still builds.
188	     *
189	     * @param array<int|string, QueueableBuilding|QueueableResearch> $steps
190	     * @param callable(PlanetService): list<BuildCandidate> $pass
191	     * @return array<int|string, QueueableBuilding|QueueableResearch>
192	     */
193	    private function withStep(array $steps, PlanetService $planet, AiProfile $profile, callable $pass, ?SavingsGoal $goal, bool $wall = false): array
194	    {
195	        $candidates = $pass($planet);
196	        $isResearch = static fn (BuildCandidate $candidate): bool => ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research;
197	
198	        // The candidate list is in priority order, so whichever queue its first entry belongs to is tried first.
199	        $queues = [$planet->getPlanetId() => false, self::LAB_STEP => true];
200	        if ($candidates !== [] && $isResearch($candidates[0])) {
201	            $queues = array_reverse($queues, true);
202	        }
203	
204	        foreach ($queues as $key => $research) {
205	            if (isset($steps[$key])) {
206	                continue;
207	            }
208	
209	            $step = $this->firstQueueable($planet, $profile, array_values(array_filter($candidates, static fn (BuildCandidate $candidate): bool => $isResearch($candidate) === $research)), $wall ? null : $goal);
210	            if ($step !== null) {
211	                $steps[$key] = $step;
212	            }
213	        }
214	
215	        return $steps;
216	    }
217	
218	    /**
219	     * The first candidate this planet can actually queue, or null when none of them is legal.
220	     *
221	     * @param list<BuildCandidate> $candidates
222	     */
223	    private function firstQueueable(PlanetService $planet, AiProfile $profile, array $candidates, ?SavingsGoal $goal): QueueableBuilding|QueueableResearch|null
224	    {
225	        foreach ($candidates as $candidate) {
226	            if (!$this->canSpendFor($planet, $goal, $candidate)) {
227	                continue;
228	            }
229	
230	            // Which queue takes a step is the host's object type, not this module's opinion: the
231	            // chain hands over prerequisites, and a technology among them is research.
232	            $step = $this->step($planet, $candidate);
233	            if ($step instanceof QueueableResearch) {
234	                if ($this->queueableResearch($planet, $candidate) === null) {
235	                    continue;
236	                }
237	
238	                return $step;
239	            }
240	
241	            if (!$this->canQueue($planet, $candidate)) {
242	                continue;
243	            }
244	
245	            return $step;
246	        }
247	
248	        return null;
249	    }
250	
251	    /**
252	     * Whether the building queue will take this candidate on this planet right now.
253	     *
254	     * Public because "the building queue cannot answer this" is a question a second planner has to
255	     * ask: a planet that cannot buy capacity here has one other route, and the yard may only take it
256	     * when this says no. The gate itself stays in one place rather than being restated next to it.
257	     */
258	    public function canQueue(PlanetService $planet, BuildCandidate $candidate): bool
259	    {
260	        return $this->refusal($planet, $candidate) === null;
261	    }
262	
263	    /**
264	     * Whether an order planned earlier can no longer be placed because the queue moved on since: the
265	     * planet's queue filled, or the station's units went into production. The executor asks this for
266	     * an order carrying its own binding, so a stale order is planned again from the live state
267	     * instead of being sent to a host gate that refuses it (STUCK: "Maximum number of items already
268	     * in queue" and shipyard_busy, repeated by the same accounts).
269	     */
270	    public function orderIsStale(int $playerId, int $planetId, int $buildingId): bool
271	    {
272	        $player = $this->playerServiceFactory->make($playerId, true);
273	        $planet = $player->planets->all()[$planetId] ?? null;
274	
275	        if ($planet === null) {
276	            foreach ($player->planets->all() as $candidate) {
277	                if ($candidate->getPlanetId() === $planetId) {
278	                    $planet = $candidate;
279	                    break;
280	                }
281	            }
282	        }
283	
284	        if ($planet === null) {
285	            return false;
286	        }
287	
288	        return $this->buildingQueueService->retrieveQueue($planet)->isQueueFull()
289	            || $player->isObjectUpgradeBlocked($buildingId);
290	    }
291	
292	    /**
293	     * Whether the station project has its turn, or the mines keep the planet's one build slot.
294	     *
295	     * A planet whose mines still repay keeps mining -- the station is the settled account's project. The
296	     * one exception is a planet the mines have outgrown: when the cheapest upgrade that still repays is a
297	     * dearer purchase than the cheapest station the catalogue offers it, the station is the small step,
298	     * and a player whose mines have reached that scale takes it. The comparison is between the planet's own
299	     * prices, so a fast universe does not age the account into it: measured live 5 Oct 2026 on the 1000x
300	     * cohort, where a mine that repays in an hour always cost more than the station behind it and the
301	     * station project waited on a mine level the cohort never reached -- no account in it owned one.
302	     *
303	     * @param list<BuildCandidate> $paying the production upgrades that still repay
304	     */
305	    private function minesOutgrownStations(PlanetService $planet, array $paying): bool
306	    {
307	        if ($paying === []) {
308	            return true;
309	        }
310	
311	        $station = $this->cheapestStationPrice($planet);
312	        if ($station === null) {
313	            return false;
314	        }
315	
316	        foreach ($paying as $candidate) {
317	            if ($this->candidatePrice($planet, $candidate) < $station) {
318	                return false;
319	            }
320	        }
321	
322	        return true;
323	    }
324	
325	    /** The price of the cheapest station this planet does not hold and can build, or null when it holds every one. */
326	    private function cheapestStationPrice(PlanetService $planet): ?float
327	    {
328	        $cheapest = null;
329	
330	        foreach (ObjectService::getStationObjects() as $station) {
331	            if ($planet->getObjectLevel($station->machine_name) > 0
332	                || !ObjectService::objectValidPlanetType($station->machine_name, $planet)) {
333	                continue;
334	            }
335	
336	            $price = $this->candidatePrice($planet, null, $station->machine_name);
337	            $cheapest = $cheapest === null ? $price : min($cheapest, $price);
338	        }
339	
340	        return $cheapest;
341	    }
342	
343	    /** What the host charges this planet for one step, by its candidate or by its machine name. */
344	    private function candidatePrice(PlanetService $planet, ?BuildCandidate $candidate, string $machineName = ''): float
345	    {
346	        if ($candidate instanceof BuildCandidate) {
347	            $machineName = ObjectService::getObjectById($candidate->buildingId)->machine_name;
348	        }
349	
350	        return ObjectService::getObjectPrice($machineName, $planet)->sum();
351	    }
352	
353	    /**
354	     * Which of the host's gates refuses this building here, or null when the planet can queue it.
355	     * The gates are asked in the order the building page asks them: planet type, free queue space,
356	     * met requirements, a balance it can pay and a field the building still fits in. Named, so a
357	     * planet that never builds says why instead of reading as idle.
358	     */
359	    public function refusal(PlanetService $planet, BuildCandidate $candidate): ?string
360	    {
361	        $object = ObjectService::getObjectById($candidate->buildingId);
362	        $machineName = $object->machine_name;
363	
364	        if (!ObjectService::objectValidPlanetType($machineName, $planet)) {
365	            return 'planet type';
366	        }
367	        if ($this->buildingQueueService->retrieveQueue($planet)->isQueueFull()) {
368	            return 'queue full';
369	        }
370	        // The host refuses an order for a station whose units are already in production, and the
371	        // executor asks the same gate (`QueueAiBuildingAction`). Not asked here, the pass offers a
372	        // step the executor then refuses: the planet spends its one step on a refusal, queues
373	        // nothing, and still reads buildable to the planner -- idle while called buildable (live:
374	        // player 44, 4 of 4 planets). Asking it here lets the planet fall through to its next
375	        // candidate instead.
376	        if ($planet->getPlayer()?->isObjectUpgradeBlocked($candidate->buildingId) === true) {
377	            return 'shipyard busy';
378	        }
379	        if (!ObjectService::objectRequirementsMetWithQueue($machineName, $planet->getObjectLevel($machineName) + 1, $planet)) {
380	            return 'requirements';
381	        }
382	        if (!$planet->hasResources($this->withReserve($planet, ObjectService::getObjectPrice($machineName, $planet), ReserveFloor::ECONOMY_HOURS))) {
383	            return 'price plus reserve';
384	        }
385	        // `BuildingQueueService::start()` refuses a field-consuming building once the planet's fields
386	        // are used up, and a terraformer cannot rescue it because a terraformer consumes a field too.
387	        if ($object->consumesPlanetField && $planet->getBuildingCount() >= $planet->getPlanetFieldMax()) {
388	            return 'no free field';
389	        }
390	
391	        return null;
392	    }
393	
394	    /**
395	     * What this planet is saving for: the price plus reserve of the first economy step the planet is
396	     * short of, or null when it is not saving. A player mines while short, so anything else that spends
397	     * the same resource waits (the shipyard leaves the balance alone until the step is paid).
398	     */
399	    public function savingFor(PlanetService $planet, AiProfile $profile): ?Resources
400	    {
401	        $candidate = $this->savingCandidate($planet, $profile);
402	
403	        return $candidate === null ? null : $this->priceWithReserve($planet, $candidate);
404	    }
405	
406	    /**
407	     * The instant this planet's next step becomes payable, or null when it waits for none: it can
408	     * already pay, or the resource it is short of is one its own mines do not make.
409	     *
410	     * Affordability here is the planner's own word -- the price plus the floor the purchase must
411	     * leave behind -- so a caller that waits for this answer waits for exactly the purchase the
412	     * queue would take, and the arithmetic lives in one place instead of once per caller.
413	     */
414	    public function savingEta(PlanetService $planet, AiProfile $profile, CarbonImmutable $now): ?CarbonImmutable
415	    {
416	        $candidate = $this->savingCandidate($planet, $profile);
417	
418	        return $candidate === null ? null : $this->payableAt($planet, $this->priceWithReserve($planet, $candidate), $now);
419	    }
420	
421	    /**
422	     * The step this planet is short of, with the instant it becomes payable, or null when it is
423	     * waiting for none. A login books it: a queue it cannot fill yet is then filled the moment the
424	     * resources arrive, instead of standing empty until the account's next login (ECON-001 -- the
425	     * read-out finds such a planet buildable while the login that passed it ordered nothing).
426	     *
427	     * @return array{0: QueueableBuilding|QueueableResearch, 1: CarbonImmutable}|null
428	     */
429	    public function savingBooking(PlanetService $planet, AiProfile $profile, CarbonImmutable $now): ?array
430	    {
431	        $candidate = $this->savingCandidate($planet, $profile);
432	        if ($candidate === null) {
433	            return null;
434	        }
435	
436	        $dueAt = $this->payableAt($planet, $this->priceWithReserve($planet, $candidate), $now);
437	
438	        return $dueAt === null ? null : [$this->step($planet, $candidate), $dueAt];
439	    }
440	
441	    /** The price of one candidate plus the floor that must survive buying it. */
442	    private function priceWithReserve(PlanetService $planet, BuildCandidate $candidate): Resources
443	    {
444	        $machineName = ObjectService::getObjectById($candidate->buildingId)->machine_name;
445	
446	        return $this->withReserve($planet, ObjectService::getObjectPrice($machineName, $planet), ReserveFloor::ECONOMY_HOURS);
447	    }
448	
449	    /** When this planet holds what the purchase needs, or null when its own income never brings it there. */
450	    private function payableAt(PlanetService $planet, Resources $needed, CarbonImmutable $now): ?CarbonImmutable
451	    {
452	        $held = $planet->getResources();
453	        $hours = 0.0;
454	
455	        foreach ([
456	            [$needed->metal->get(), $held->metal->get(), $planet->getMetalProductionPerHour()],
457	            [$needed->crystal->get(), $held->crystal->get(), $planet->getCrystalProductionPerHour()],
458	            [$needed->deuterium->get(), $held->deuterium->get(), $planet->getDeuteriumProductionPerHour()],
459	        ] as [$cost, $stored, $perHour]) {
460	            if ($cost <= $stored) {
461	                continue;
462	            }
463	
464	            if ($perHour <= 0.0) {
465	                return null;
466	            }
467	
468	            $hours = max($hours, ($cost - $stored) / $perHour);
469	        }
470	
471	        return $hours <= 0.0 ? null : $now->addSeconds((int) ceil($hours * 3600.0));
472	    }
473	
474	    /** The order a candidate turns into, on the queue the host's own object type says it belongs to. */
475	    private function step(PlanetService $planet, BuildCandidate $candidate): QueueableBuilding|QueueableResearch
476	    {
477	        $fields = ['planetId' => $planet->getPlanetId(), 'reason' => $candidate->reason];
478	
479	        return ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research
480	            ? app()->makeWith(QueueableResearch::class, [...$fields, 'researchId' => $candidate->buildingId])
481	            : app()->makeWith(QueueableBuilding::class, [...$fields, 'buildingId' => $candidate->buildingId]);
482	    }
483	
484	    /** The first step in the planner's own order this planet cannot yet pay for, or null when it can pay for all of them. */
485	    private function savingCandidate(PlanetService $planet, AiProfile $profile): ?BuildCandidate
486	    {
487	        foreach ($this->passes($profile) as $pass) {
488	            foreach ($pass($planet) as $candidate) {
489	                if ($this->refusal($planet, $candidate) === 'price plus reserve') {
490	                    return $candidate;
491	                }
492	            }
493	        }
494	
495	        return null;
496	    }
