498	    /**
499	     * What this planet is holding resources back for, or null when it spends freely.
500	     *
501	     * Only a goal saver holds anything back (PERS-007). The strategy decides how the pile is spent, never
502	     * whether the account spends at all: every other strategy leaves the balance alone, so the decision
503	     * doctrine's spend-first rule stands for the immediate spender. The goal is the first step the planet
504	     * cannot yet pay for -- the step it would buy the moment it could -- and no object is named here, so
505	     * a goal it reaches is replaced by the next one with no edit.
506	     */
507	    private function savingsGoal(PlanetService $planet, AiProfile $profile): ?SavingsGoal
508	    {
509	        // The profile's own cast is the gate: a strategy the module does not manage leaves the
510	        // balance alone, so nothing is held back and the account spends as before.
511	        if ($profile->stockpile_strategy !== AiStockpileStrategy::GoalSaver) {
512	            return null;
513	        }
514	
515	        // A score that has not moved for the window is a goal that is not arriving: the account stops reserving the
516	        // pile for it and spends what it holds (IMPL-69), the same release the reserve floor makes.
517	        if (app(StalledGrowthDetector::class)->stalled($profile->player_id)) {
518	            return null;
519	        }
520	
521	        $candidate = $this->savingCandidate($planet, $profile);
522	        if ($candidate === null) {
523	            return null;
524	        }
525	
526	        $machineName = ObjectService::getObjectById($candidate->buildingId)->machine_name;
527	
528	        return app()->makeWith(SavingsGoal::class, [
529	            'cost' => ObjectService::getObjectPrice($machineName, $planet),
530	            'objectId' => $candidate->buildingId,
531	        ]);
532	    }
533	
534	    /**
535	     * Whether the planet can pay for this candidate out of what the goal leaves spendable.
536	     *
537	     * A saving player holds the goal's price back and spends what is left over, so a cheaper upgrade
538	     * that would burn the reserved pile waits its turn. The goal's own purchase is the exception:
539	     * spending the reserve is what the reserve is for.
540	     *
541	     * The comparison is against the price alone, because the reserve already is the margin that must
542	     * survive the purchase: the goal was named precisely because the planet cannot yet pay its price
543	     * plus the same floor, so spendable = available - reserved is always below that floor and a price
544	     * plus floor again can never fit inside it. Measured that way the branch never passes and a goal
545	     * saver stops playing entirely -- frozen on every planet until the goal is reached, which is the
546	     * strategy deciding *whether* the account spends rather than how (PERS-007). Every other spend
547	     * still has to clear refusal()'s price-plus-reserve gate, so the floor is not lost, only not
548	     * charged twice against the reserve that exists to carry it.
549	     */
550	    private function canSpendFor(PlanetService $planet, ?SavingsGoal $goal, BuildCandidate $candidate): bool
551	    {
552	        if ($goal === null || $goal->covers($candidate->buildingId)) {
553	            return true;
554	        }
555	
556	        $price = ObjectService::getObjectPrice(ObjectService::getObjectById($candidate->buildingId)->machine_name, $planet);
557	        $spendable = $goal->spendable($planet->getResources());
558	
559	        return $spendable->metal->get() >= $price->metal->get()
560	            && $spendable->crystal->get() >= $price->crystal->get()
561	            && $spendable->deuterium->get() >= $price->deuterium->get();
562	    }
563	
564	    /**
565	     * The same question for a technology, asked the way the host's research page asks it.
566	     *
567	     * Research is account-wide on the host's screen while its queue and its requirements are per
568	     * planet, so the planet that answers is the planet whose laboratory carries it. Nothing here
569	     * names a technology: the price, the requirement graph and the queue are all the host's.
570	     */
571	    private function queueableResearch(PlanetService $planet, BuildCandidate $candidate): ?QueueableResearch
572	    {
573	        $machineName = ObjectService::getObjectById($candidate->buildingId)->machine_name;
574	
575	        // A technology already in research anywhere on the account is not offered again: the host
576	        // would take the row and then cancel it, so the capability is withheld instead of the
577	        // decision being spent on a refusal.
578	        if ($this->researchQueueService->activeResearchQueueItemCount($planet->getPlayer(), $candidate->buildingId) > 0) {
579	            return null;
580	        }
581	
582	        $queueable = !$this->researchQueueService->retrieveQueue($planet)->isQueueFull()
583	            && ObjectService::objectRequirementsMetWithQueue($machineName, ($planet->getPlayer()?->getResearchLevel($machineName) ?? 0) + 1, $planet)
584	            && $planet->hasResources($this->withReserve($planet, ObjectService::getObjectPrice($machineName, $planet), ReserveFloor::RESEARCH_HOURS));
585	
586	        if (!$queueable) {
587	            return null;
588	        }
589	
590	        return app()->makeWith(QueueableResearch::class, [
591	            'planetId' => $planet->getPlanetId(),
592	            'researchId' => $candidate->buildingId,
593	            'reason' => $candidate->reason,
594	        ]);
595	    }
596	
597	    /**
598	     * The price plus the floor the purchase must leave behind, so affordability stays one host call.
599	     *
600	     * A resource the price does not spend keeps no floor: the floor is what must survive spending that
601	     * resource, so a purchase that costs no deuterium is not blocked by a deuterium reserve (SP5 --
602	     * saving for a drive must not freeze surplus metal and crystal).
603	     */
604	    private function withReserve(PlanetService $planet, Resources $price, float $savingHours): Resources
605	    {
606	        $floor = $this->reserveFloor->floor($planet, $savingHours);
607	
608	        return new Resources(
609	            $price->metal->get() > 0 ? $price->metal->get() + $floor->metal->get() : 0,
610	            $price->crystal->get() > 0 ? $price->crystal->get() + $floor->crystal->get() : 0,
611	            $price->deuterium->get() > 0 ? $price->deuterium->get() + $floor->deuterium->get() : 0,
612	            $price->energy->get(),
613	        );
614	    }
615	}

