21	/**
22	 * A settled account whose mines no longer repay their next level, with every station but the nano
23	 * factory standing and every facility it waits on already up. The terraformer is what a deep planet
24	 * built to keep its fields.
25	 */
26	function stationGoalMature(Situation $situation): Situation
27	{
28	    return $situation
29	        ->resources(20_000_000, 10_000_000, 2_000_000)
30	        ->level('metal_mine', 28)
31	        ->level('crystal_mine', 28)
32	        ->level('deuterium_synthesizer', 28)
33	        ->level('solar_plant', 40)
34	        ->level('metal_store', 14)
35	        ->level('crystal_store', 14)
36	        ->level('deuterium_store', 14)
37	        ->level('terraformer', 25)
38	        ->level('shipyard', 2)
39	        ->level('research_lab', 11)
40	        ->level('alliance_depot', 1)
41	        ->level('missile_silo', 1)
42	        ->level('space_dock', 1)
43	        ->research('computer_technology', 10);
44	}
45	
46	/**
47	 * Every planet of the account stands a wall, so the login writes no unit order: the host refuses a
48	 * yard upgrade while ships or defence are in production, and a login that orders a wall first would
49	 * spend its station order on that refusal instead.
50	 */
51	function stationGoalWall(int $playerId): void
52	{
53	    foreach (app(PlayerServiceFactory::class)->make($playerId, true)->planets->all() as $planet) {
54	        $planet->addUnit('rocket_launcher', 300);
55	    }
56	}
