58	/** Every step the plan offers this planet, in the planner's own order, so a failure names them. */
59	function stationGoalSteps(PlanetService $planet): string
60	{
61	    $profile = AiProfile::query()->where('player_id', $planet->getPlayer()?->getId())->firstOrFail();
62	    $planet->updateResources(false);
63	    $planet->updateResourceProductionStats(false);
64	    $planet->updateResourceStorageStats(false);
65	
66	    return implode(', ', array_map(
67	        static fn ($candidate): string => $candidate->reason,
68	        app(QueueableBuildingPlanner::class)->passes($profile)['routine']($planet),
69	    ));
70	}
