 17	/**
 18	 * An archetype's written doctrine (`resources/doctrine/<archetype>.yaml`): the opening build order, the
 19	 * research path, and the fleet and defence templates (architecture step 4).
 20	 *
 21	 * The files name objects, as data (Gate 1 as amended 3 Oct 2026). This class names none: an entry the host
 22	 * does not have is skipped, and when a list is done or a template holds nothing the host can build, the
 23	 * caller's generic rule decides, so a modded object stays reachable.
 24	 *
 25	 * Which list the account follows is its phase (`phases: <phase>: <key>`, architecture step 4), and the
 26	 * flat list is the fallback every other phase reads: a file without a phase block behaves exactly as
 27	 * before, and a guide can send an opening account down a different path from a settled one.
 28	 */
 29	class ArchetypeDoctrine
 30	{
 31	    private const DIRECTORY = '/resources/doctrine/';
 32	
 33	    /** @var array<string, array<string, mixed>> */
 34	    private static array $files = [];
 35	
 36	    /**
 37	     * The next opening step this planet has not reached, as a building candidate: the build list runs in
 38	     * order, a step already done is skipped, and research steps are left to the research path.
 39	     *
 40	     * @return list<BuildCandidate>
 41	     */
 42	    public function openingStep(AiArchetype $archetype, PlanetService $planet): array
 43	    {
 44	        // The opening is a planet's: a moon has a handful of fields and starts with the lunar base, which
 45	        // the facility chain places (measured live 4 Oct 2026: moons built a shipyard first and never a lunar base).
 46	        if ($planet->getPlanetType() === PlanetType::Moon) {
 47	            return [];
 48	        }
 49	
 50	        foreach ($this->steps($archetype, 'opening', $this->phase($planet->getPlayer())) as [$machineName, $level]) {
 51	            $object = $this->object($machineName);
 52	            if ($object === null || $object->type === GameObjectType::Research) {
 53	                continue;
 54	            }
 55	            if (!ObjectService::objectValidPlanetType($machineName, $planet)) {
 56	                continue;
 57	            }
 58	            if ($planet->getObjectLevel($machineName) >= $level) {
 59	                continue;
 60	            }
 61	
 62	            return [new BuildCandidate($object->id, 'doctrine:opening:' . $machineName . ':' . $level)];
 63	        }
 64	
 65	        return [];
 66	    }
 67	
 68	    /**
 69	     * The next technology on the archetype's path the account has not reached (the opening's research rows
 70	     * first, then the path), as a candidate for the lab.
 71	     *
 72	     * @return list<BuildCandidate>
 73	     */
 74	    public function researchStep(AiArchetype $archetype, PlayerService $player): array
 75	    {
 76	        $phase = $this->phase($player);
 77	        $rows = [...$this->steps($archetype, 'opening', $phase), ...$this->steps($archetype, 'research_path', $phase)];
 78	
 79	        foreach ($rows as [$machineName, $level]) {
 80	            $object = $this->object($machineName);
 81	            if ($object === null || $object->type !== GameObjectType::Research) {
 82	                continue;
 83	            }
 84	            if ($player->getResearchLevel($machineName) >= $level) {
 85	                continue;
 86	            }
 87	
 88	            return [new BuildCandidate($object->id, 'doctrine:research:' . $machineName . ':' . $level)];
 89	        }
 90	
 91	        return [];
 92	    }
 93	
 94	    /**
 95	     * The template's hull furthest below its share of what the account owns, among the hulls `$buildable`
 96	     * accepts; null when the archetype has no template or nothing in it can be built.
 97	     *
 98	     * @param array<string, int> $owned machine name => units the account owns
 99	     * @param callable(string): bool $buildable
100	     */
101	    public function nextTemplateUnit(AiArchetype $archetype, string $template, array $owned, callable $buildable): ?string
102	    {
103	        $shares = $this->file($archetype)[$template] ?? [];
104	        if (!is_array($shares) || $shares === []) {
105	            return null;
106	        }
107	
108	        $total = max(1, array_sum(array_map(static fn (string $name): int => $owned[$name] ?? 0, array_keys($shares))));
109	        $weight = max(1, array_sum($shares));
110	        $best = null;
111	        $bestGap = -INF;
112	
113	        foreach ($shares as $machineName => $share) {
114	            if ($this->object((string) $machineName) === null || !$buildable((string) $machineName)) {
115	                continue;
116	            }
117	
118	            $gap = ((float) $share / $weight) - (($owned[$machineName] ?? 0) / $total);
119	            if ($gap > $bestGap) {
120	                $best = (string) $machineName;
121	                $bestGap = $gap;
122	            }
123	        }
124	
125	        return $best;
126	    }
127	
128	    /**
129	     * The account's game phase, which decides which list a guide's file gives it (architecture step 4).
130	     * No player (a detached planet read) leaves the phase unknown, and an unknown phase follows the flat
131	     * list, so nothing that reads the doctrine can be broken by a missing owner.
